                    && !lexer.isEnabled(Feature.DisableSpecialKeyDetect)) {
                String typeName = lexer.scanSymbol(symbolTable, '"');
                if (lexer.isEnabled(Feature.IgnoreAutoType)) {
                    continue;
                }

                Class<?> clazz = config.checkAutoType(typeName, null, lexer.getFeatures());
                if (clazz == null) {
                    map.put(JSON.DEFAULT_TYPE_KEY, typeName);
                    continue;
                }

                ObjectDeserializer deserializer = config.getDeserializer(clazz);
                if (deserializer == null) {
                    throw new JSONException("cannot get javaBeanDeserializer. " + clazz.getName());
                }

                lexer.nextToken(JSONToken.COMMA);
                if (lexer.token() == JSONToken.RBRACE) {
                    lexer.nextToken();
                    try {
                        Object instance = deserializer.deserialze(this, clazz, fieldName);
                        return instance;
                    } catch (Exception e) {
                        throw new JSONException("create instance error", e);
                    }
                }

                this.setResolveStatus(DefaultJSONParser.TypeNameRedirect);
                this.parseObject(object, fieldName);
                return TypeUtils.cast(object, clazz, this.config);
            } else if (key == "$ref"
                    && context != null
                    && !lexer.isEnabled(Feature.DisableSpecialKeyDetect)) {
                lexer.nextToken(JSONToken.LITERAL_STRING);
                if (lexer.token() == JSONToken.LITERAL_STRING) {
                    String ref = lexer.stringVal();
                    lexer.nextToken(JSONToken.RBRACE);
                    setContextFlag = true;
                    if (lexer.token() == JSONToken.RBRACE) {
                        lexer.nextToken();
                    }
                    if ("@".equals(ref)) {
                        return this.context.object;
                    } else if ("$".equals(ref)) {
                        ParseContext rootContext = context;
                        while (rootContext.parent != null) {
                            rootContext = rootContext.parent;
                        }
                        return rootContext.object;
                    } else {
                        throw new JSONException("illegal ref, " + ref);
                    }
                } else {
                    throw new JSONException("illegal ref");
                }
            }

            if (!setContextFlag) {
                if (this.context != null && fieldName == this.context.fieldName && object == this.context.object) {
                    context = this.context;
                } else {
                    ParseContext contextR = setContext(object, fieldName);
                    if (context == null) {
                        context = contextR;
                    }
                    setContextFlag = true;
                }
            }

            // Parse the value based on lexer token
            if (ch == '"') {
                lexer.scanString();
                value = lexer.stringVal();
                map.put(key, value);
            } else if (ch >= '0' && ch <= '9' || ch == '-') {
                lexer.scanNumber();
                if (lexer.token() == JSONToken.LITERAL_INT) {
                    value = lexer.integerValue();
                } else {
                    value = lexer.decimalValue(lexer.isEnabled(Feature.UseBigDecimal));
                }
                map.put(key, value);
            } else if (ch == '[') {
                lexer.nextToken();
                JSONArray list = new JSONArray();
                this.parseArray(list, key);
                if (lexer.isEnabled(Feature.UseObjectArray)) {
                    value = list.toArray();
                } else {
                    value = list;
                }
                map.put(key, value);
                if (lexer.token() == JSONToken.RBRACE) {
                    lexer.nextToken();
                    return object;
                }
                continue;
            } else if (ch == '{') {
                lexer.nextToken();
                Map<Object, Object> obj = new LinkedHashMap<>();
                value = this.parseObject(obj, key);
                map.put(key, value);
                if (lexer.token() == JSONToken.RBRACE) {
                    lexer.nextToken();
                    return object;
                }
                continue;
            } else {
                lexer.nextToken();
                value = parse();
                map.put(key, value);
                if (lexer.token() == JSONToken.RBRACE) {
                    lexer.nextToken();
                    return object;
                }
                continue;
            }

            lexer.skipWhitespace();
            ch = lexer.getCurrent();
            if (ch == ',') {
                lexer.next();
                continue;
            } else if (ch == '}') {
                lexer.next();
                lexer.resetStringPosition();
                lexer.nextToken();
                return object;
            } else {
                throw new JSONException("syntax error, position at " + lexer.pos() + ", name " + key);
            }
        }
    } finally {
        this.setContext(context);
    }
}
